const d = msg.payload;
const toNum = (val) => (val === true || val === 1) ? 1 : 0;

// 1. Saída 1: Sensores Analógicos (measurement: "sensores_analogicos")
const msgAnalogicos = {
    measurement: "sensores_analogicos",
    payload: [
        {
            nivel: Number(d.Nivel ?? 0),
            temperatura: Number(d.Temperatura ?? 0),
            corrente: Number(d.DP2200_LEITURA ?? 0),
            dp2200_status: Number(d.DP2200_STATUS ?? 0),
            pressao: Number(d.PN2594_PRESSAO ?? 0),
            capacitancia: Number(d.LMT100_CAPACITANCIA ?? 0)
        },
        { bancada: "didatica_01" }
    ]
};

// 2. Saída 2: Sensores Digitais (measurement: "sensores_digitais")
const msgDigitaisSensores = {
    measurement: "sensores_digitais",
    payload: [
        {
            pn2594_sp1: toNum(d.PN2594_83),
            pn2594_out2: toNum(d.PN2594_83_1),
            lmt100_na: toNum(d.LMT100_NA),
            lmt100_nf: toNum(d.LMT100_NF)
        },
        { bancada: "didatica_01" }
    ]
};

// 3. Saída 3: Entradas e Saídas do CLP (measurement: "clp_io")
const msgCLP = {
    measurement: "clp_io",
    payload: [
        {
            // Entradas
            status_emer: toNum(d.STATUS_B_EMER),
            status_liga: toNum(d.STATUS_B_LIGA),
            status_desliga: toNum(d.STATUS_B_DESLIGA),
            status_reset: toNum(d.STATUS_B_RESET),
            status_do0_inv: toNum(d.STATUS_DOO_INV),
            status_do2_inv: toNum(d.STATUS_DO2_INV),
            // Saídas
            led_liga: toNum(d.LED_B_LIGA),
            led_desliga: toNum(d.LED_B_DESLIGA),
            led_reset: toNum(d.LED_B_RESET),
            aciona_valvula: toNum(d.ACIONA_VALVULA),
            rele_2: toNum(d.RELE_INTERFACE_2),
            rele_3: toNum(d.RELE_INTERFACE_3),
            di0_inv: toNum(d.DIO_INV),
            di2_inv: toNum(d.DI2_INV)
        },
        { bancada: "didatica_01" }
    ]
};

return [msgAnalogicos, msgDigitaisSensores, msgCLP];
